using System;using System.Diagnostics;using System.Text;using System.Text.RegularExpressions;using System.Windows;using System.Windows.Documents;using System.Windows.Media;
namespace TrayLeaf {
 internal static class MarkdownView {
  internal static FlowDocument Render(string markdown,Window owner){var doc=new FlowDocument{FontFamily=owner.FontFamily,FontSize=owner.FontSize,PagePadding=new Thickness(22),ColumnWidth=Double.PositiveInfinity};doc.SetResourceReference(FlowDocument.ForegroundProperty,"Text");doc.SetResourceReference(FlowDocument.BackgroundProperty,"Surface");var lines=(markdown??"").Replace("\r\n","\n").Split('\n');bool code=false;var buffer=new StringBuilder();foreach(string raw in lines){string line=raw.TrimEnd();if(line.TrimStart().StartsWith("```")){if(code){var block=new Paragraph(new Run(buffer.ToString())){FontFamily=new FontFamily("Consolas"),Padding=new Thickness(12),Margin=new Thickness(0,8,0,12)};block.SetResourceReference(Paragraph.BackgroundProperty,"Subtle");doc.Blocks.Add(block);buffer.Length=0;}code=!code;continue;}if(code){buffer.AppendLine(raw);continue;}if(String.IsNullOrWhiteSpace(line))continue;
    if(Regex.IsMatch(line,"^\\s*([-*_])(?:\\s*\\1){2,}\\s*$")){var rule=new Paragraph{BorderThickness=new Thickness(0,1,0,0),Margin=new Thickness(0,12,0,12)};rule.SetResourceReference(Paragraph.BorderBrushProperty,"Line");doc.Blocks.Add(rule);continue;}
    var heading=Regex.Match(line,"^(#{1,6})\\s+(.+)$");var list=Regex.Match(line,"^\\s*(?:[-*+] |(\\d+)[.)] )(.+)$");var p=new Paragraph{Margin=new Thickness(0,5,0,9),LineHeight=owner.FontSize*1.65};if(heading.Success){p.FontSize=owner.FontSize+Math.Max(1,7-heading.Groups[1].Length)*2;p.FontWeight=FontWeights.SemiBold;p.Margin=new Thickness(0,18,0,10);Inline(p.Inlines,heading.Groups[2].Value);}else if(list.Success){p.Margin=new Thickness(16,3,0,6);p.Inlines.Add(new Run(list.Groups[1].Success?list.Groups[1].Value+". ":"• "));Inline(p.Inlines,list.Groups[2].Value);}else if(line.StartsWith(">")){p.BorderThickness=new Thickness(3,0,0,0);p.SetResourceReference(Paragraph.BorderBrushProperty,"Accent");p.Padding=new Thickness(12,4,0,4);Inline(p.Inlines,line.TrimStart('>',' '));}else if(line.StartsWith("|")){if(Regex.IsMatch(line,"^[| :\\-]+$"))continue;p.FontFamily=new FontFamily("Consolas");Inline(p.Inlines,line.Trim('|').Replace("|","  ·  "));}else Inline(p.Inlines,line);doc.Blocks.Add(p);
   }if(buffer.Length>0)doc.Blocks.Add(new Paragraph(new Run(buffer.ToString())){FontFamily=new FontFamily("Consolas")});return doc;}
  static void Inline(InlineCollection collection,string text){var pattern=new Regex(@"(\[[^\]]+\]\(https?://[^\s)]+\)|\*\*[^*]+\*\*|__[^_]+__|`[^`]+`|\*[^*]+\*|~~[^~]+~~)");int offset=0;foreach(Match m in pattern.Matches(text)){if(m.Index>offset)collection.Add(new Run(text.Substring(offset,m.Index-offset)));string token=m.Value;if(token.StartsWith("[")){int split=token.IndexOf("](",StringComparison.Ordinal);Uri url;if(Uri.TryCreate(token.Substring(split+2,token.Length-split-3),UriKind.Absolute,out url)&&(url.Scheme=="https"||url.Scheme=="http")){var link=new Hyperlink(new Run(token.Substring(1,split-1))){NavigateUri=url};link.RequestNavigate+=delegate(object s,System.Windows.Navigation.RequestNavigateEventArgs e){try{Process.Start(new ProcessStartInfo(e.Uri.AbsoluteUri){UseShellExecute=true});}catch{}e.Handled=true;};collection.Add(link);}else collection.Add(new Run(token));}else if(token.StartsWith("**")||token.StartsWith("__"))collection.Add(new Bold(new Run(token.Substring(2,token.Length-4))));else if(token.StartsWith("`")){var r=new Run(token.Substring(1,token.Length-2)){FontFamily=new FontFamily("Consolas")};r.SetResourceReference(Run.BackgroundProperty,"Subtle");collection.Add(r);}else if(token.StartsWith("~~"))collection.Add(new Run(token.Substring(2,token.Length-4)){TextDecorations=TextDecorations.Strikethrough});else collection.Add(new Italic(new Run(token.Substring(1,token.Length-2))));offset=m.Index+m.Length;}if(offset<text.Length)collection.Add(new Run(text.Substring(offset)));}
 }
}
